import pytest
from prog.solution import wrap

def test_wrap_single_line():
    result = wrap("Hello, world!", 10)
    assert result == ["Hello, world!"], "Single line should not be split"

def test_wrap_multiple_lines():
    result = wrap("This is a long sentence that needs to be wrapped.", 10)
    assert result == ["This is a", "long sentence", "that needs to", "be wrapped."], "Sentence should be split into multiple lines"

def test_wrap_with_spaces():
    result = wrap("  Leading and trailing spaces  ", 10)
    assert result == ["  Leading and", "trailing spaces  "], "Spaces at the start and end should be preserved"

def test_wrap_with_single_char():
    result = wrap("a", 1)
    assert result == ["a"], "Single character should not be split"

def test_wrap_with_zero_cols():
    with pytest.raises(ValueError):
        wrap("Hello, world!", 0), "Zero column width should raise ValueError"

def test_wrap_with_negative_cols():
    with pytest.raises(ValueError):
        wrap("Hello, world!", -1), "Negative column width should raise ValueError"

